%Test program for the function grid_dke_yp.m that generates all the non-uniform grids for the DKE solver%%by J. Decker <jodecker@mit.edu> (MIT/RLE) and Y.Peysson <yves.peysson@cea.fr>(CEA/DRFC)%clear allclose all%Rp_norm = 1;rho_S = [0.3];%[0.05,[0.1:0.2:0.9],0.95];%Values of the radial flux grid [1,p] (If one radial value: local calculation only)nmhu_S_in = 109;%Number of angular values for the flux grid (WARNING: odd number) (>100 recommended for accurate run)np_S_in = 110;%Number of momentum values for the flux grid (pnmax/np < 0.1 highly recommended for accurate run)pnmax_S_in = 10;%Maximum value of the flux momentum grid (pth_ref)rho_display_in = 0.551;%Approximate radial value at which results are displayed if display_mode >= 1 [1,1]%%Pitch-angle grid parameter%sfac0_in = 1;%Reduction factor for fine grid near mhu = 0sfac1_in = 2;%Reduction factor for fine grid near mhu = 1sfact_in = 3;%Reduction factor for fine grid near mhu = mhut%snmhu0_in = 5;%Number of fine grid points near mhu = 0snmhu1_in = 2;%Number of fine grid points near mhu = 1snmhut_in = 3;%Number of fine grid points near mhu = mhut%%Momentum grid parameters%snp_in = 10;% pgridfactor%sfac_in = [sfac0_in,sfac1_in,sfact_in];snmhu_in = [snmhu0_in,snmhu1_in,snmhut_in];%disp(' ');info_dke_yp(1,'Test of the function that generates the non-uniform grids');disp(' ');%dke_mode = input_dke_yp('Grid type: (0) -> Fokker-Planck solver, (1) -> Drift Kinetic solver',0);grid_method = input_dke_yp('Pitch-angle grid calculation technique: (0) -> old method, (1) -> new method',1);grid_uniformity = input_dke_yp('Pitch-angle and momentum grids uniformity: (0) -> no, (1) -> yes',0);%[pn,dpn,pnm,dpnm,pnp,dpnp,pn_S,...    mhu,dmhu,mhum,dmhum,mhup,dmhup,mhu_S,...    xia,xrho,xdrho,xrhom,xdrhom,xrhop,xdrhop,xrho_S,rdke,...    rho_display,ir_display] = grid_dke_yp(grid_method,grid_uniformity,dke_mode,Rp_norm,rho_S,nmhu_S_in,np_S_in,pnmax_S_in,sfac_in,snmhu_in,snp_in,rho_display_in);%Grid calculations%nmhu = length(mhu);;nmhu_S = length(mhu_S);%disp(' ');info_dke_yp(2,'Pitch angle grid vector lengths')disp('Lengths of mhu / dmhu / mhum / dmhum / mhup / dmhup / mhu_S')disp(['           ',int2str(length(mhu)),' /  ',int2str(length(dmhu)),' /  ',int2str(length(mhum)),' /   ',int2str(length(dmhum)),' /  ',int2str(length(mhup)),' /   ',int2str(length(dmhup)),' /   ',int2str(length(mhu_S))])%disp(' ');info_dke_yp(2,'Momentum grid vector lengths')disp('Lengths of pn / dpn / pnm / dpnm / pnp / dpnp / pn_S')disp(['          ',int2str(length(pn)),' / ',int2str(length(dpn)),' / ',int2str(length(pnm)),' /  ',int2str(length(dpnm)),' / ',int2str(length(pnp)),' /  ',int2str(length(dpnp)),' /  ',int2str(length(pn_S))])%disp(' ');info_dke_yp(2,'Radial grid vector lengths')disp('Lengths of  xrho / xdrho / xrhom / xdrhom / xrhop / xdrhop / xrho_S')disp(['               ',int2str(length(xrho)),' /',int2str(length(xdrho)),' / ',int2str(length(xrhom)),' / ',int2str(length(xdrhom)),' / ',int2str(length(xrhop)),' / ',int2str(length(xdrhop)),' / ',int2str(length(xrho_S))])%xmhut = sqrt(2*xia./(1+xia))dmhu_ref = 2/(nmhu_S-1);%Grid step for uniform grid%figure(1),clfhold on%for i=1:nmhu,    if abs(mhu(i)) <= 1,plot([0,mhu(i)],[0,sqrt(1 - mhu(i)^2)],'b'),endendfor i=1:nmhu_S,    if abs(mhu_S(i)) <= 1,plot([0,mhu_S(i)],[0,sqrt(1-mhu_S(i)^2)],'g'),endendfor i=1:length(xmhut),	 if abs(xmhut(i)) <= 1,plot([0,xmhut(i)],[0,sqrt(1-xmhut(i)^2)],'r',[-xmhut(i),0],[sqrt(1-xmhut(i)^2),0],'r'),endendhold offaxis('equal')ylabel('pperp')xlabel('ppar')title('Pitch-angle grids: Green -> flux, Blue -> distribution, Red -> T/P boundary');zoom on%figure(2),clfplot([1:nmhu]-1+1/2,mhu,'b+',[1:nmhu_S]-1,mhu_S,'rx'),grid on,zoom onylabel('mhu')xlabel('Index')title('Pitch-angle grid')%figure(3),clfplot([1:nmhu]-1+1/2,dmhu,'b-',[1:nmhu]-1+1/2,dmhu,'bx',[1:nmhu]-1+1/2,zeros(size(dmhu))+dmhu_ref,'g-.')hold onfor i=1:length(xmhut)	jmax = max(find(mhu < xmhut(i)));%mhu > 0 	jmin = min(find(mhu > -xmhut(i)));%mhu < 0     jtmax = jmax-1+1/4;	jtmin = jmin-1+1/4;    plot([jtmax,jtmax],[0,dmhu_ref],'r')    plot([jtmin,jtmin],[0,dmhu_ref],'r')end hold offylabel('dmhu')xlabel('Index')title(['Pitch-angle grid steps: Blue -> Flux, Red -> T/P boundary, Green -> Uniform grid (',int2str(nmhu_S_in),' pts)']);grid onzoom on%nr = length(xrho);nr_S = length(xrho_S);%figure(4),clfplot([1:nr]-1+1/2,xrho,'b+',[1:nr_S]-1,xrho_S,'rx',[rdke(ir_display)-1+1/2,rdke(ir_display)-1+1/2],[0,1],'g-.',[0,nr],[rho_display,rho_display],'g-.'),grid onylabel('rho')xlabel('Index')title('Radial grid')zoom on%npn = length(pn);npn_S = length(pn_S);%figure(5),clfplot([1:npn]-1+1/2,pn,'b+',[1:npn_S]-1,pn_S,'rx'),grid onylabel('p')xlabel('Index')title('Momentum grid')zoom on%